//! 🏔️ Literal terrain parameters and mesh identity with exact native IEEE companions.
use super::GisTerrainSnapshot;
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Projection,Cell,FloatColumn,FloatRow,insert_ieee754,Reconstruction,NativeEncodingBound}}};
const SCALAR:&[FloatColumn]=&[FloatColumn::Binary64(1)];
impl ArtifactSqliteSnapshot for GisTerrainSnapshot{
 fn decode_sqlite_snapshot_native(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{
  let limits=control.limits();control.checkpoint(SqliteSnapshotPhase::DecodeNative,0,0)?;let length=match payload{store::os_io::IoPayload::Binary(bytes)=>bytes.len(),store::os_io::IoPayload::Text(text)=>text.len()};if length>limits.max_file_bytes{return Err("terrain native input exceeds file byte limit".into())}
  let mut progress=|state:protocol::native_decoding::NativeDecodeProgress|control.checkpoint(SqliteSnapshotPhase::DecodeNative,state.completed,state.total).is_ok();let mut native=dsl::NativeDecodeControl::new(limits.max_value_bytes,&mut progress);let spec=<Self as store::ArtifactPack>::record_spec().ok_or("terrain logical RecordSpec missing")?;
  let record=match payload{store::os_io::IoPayload::Binary(bytes)=>{let body=store::semio_format::unwrap_binary_controlled(bytes,"gis.gisterrain",store::semio_format::Component::Pack,1,&mut native).map_err(|e|e.to_string())?;store::pack_rt::decode_document_controlled(body,&spec,&store::PackDecodeOptions::default(),&mut native).map_err(|e|e.to_string())?.0},store::os_io::IoPayload::Text(text)=>{let body=store::semio_format::split_text_preamble_controlled(text,"gis.gisterrain",store::semio_format::Component::Dsl,1,&mut native).map_err(|e|e.to_string())?;dsl::schema::parse_exact_controlled(body,&spec,&dsl::ParseOptions{limits:dsl::Limits::default(),mode:dsl::SourceMode::Document},&mut native).map_err(|e|e.message)?}};
  super::owned_pack::reconstruct_record_controlled(&record,&mut native,limits.max_rows)
 }

 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut bound=NativeEncodingBound::new(control)?;bound.add(4096)?;bound.repeated(self.imported_features_json.len(),6)?;if let Some(child)=&self.mesh{for text in[&child.child_id,&child.target.artifact_id,&child.target.dialect.artifact_kind,&child.target.dialect.standard,&child.target.dialect.subset]{bound.repeated(text.len(),6)?;}}bound.finish()}
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,if self.mesh.is_some(){3}else{2})?;control.check_rows(if self.mesh.is_some(){3}else{2})?;let mut bytes=48usize.checked_add(self.imported_features_json.len()).ok_or("GIS terrain byte count overflow")?;if let Some(c)=&self.mesh{bytes=bytes.checked_add(8).ok_or("GIS terrain byte count overflow")?;for text in[&c.child_id,&c.target.artifact_id,&c.target.dialect.artifact_kind,&c.target.dialect.standard,&c.target.dialect.subset]{bytes=bytes.checked_add(text.len()).ok_or("GIS terrain byte count overflow")?;}}control.check_value_bytes(bytes)?;let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;p.insert("gis_terrain_document",&[])?;insert_ieee754(&mut p,"gis_terrain_parameters",&[Cell::Real(self.exaggeration),Cell::Text(&self.imported_features_json)],SCALAR)?;if let Some(c)=&self.mesh{p.insert("gis_terrain_mesh_child",&[Cell::Text(&c.child_id),Cell::Text(&c.target.artifact_id),Cell::Text(&c.target.dialect.artifact_kind),Cell::Text(&c.target.dialect.standard),Cell::Text(&c.target.dialect.subset)])?;}p.finish()}
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits()).map_err(|e|e.to_string())?;control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;let doc=database.table("gis_terrain_document")?.single_row()?;let parameters=database.table("gis_terrain_parameters")?.single_row()?;if doc.values.len()!=1||doc.integer(0)?!=doc.rowid||parameters.values.len()!=5||parameters.integer(0)?!=parameters.rowid||parameters.rowid!=doc.rowid{return Err("GIS terrain parameter ownership differs".into())}let exaggeration=FloatRow::new(parameters,SCALAR)?.real(1)?;let mesh=database.table("gis_terrain_mesh_child")?;if mesh.rows.len()>1{return Err("GIS terrain mesh ownership differs".into())}let mut owned=Reconstruction::new(control)?;owned.scalar()?;let imported_features_json=owned.text(parameters.text(2)?)?;let mesh=if let Some(row)=mesh.rows.first(){if row.values.len()!=6||row.integer(0)?!=row.rowid||row.rowid!=doc.rowid{return Err("GIS terrain mesh ownership differs".into())}Some(store::ArtifactChild::new(owned.text(row.text(1)?)?,store::os_io::ArtifactRef{artifact_id:owned.text(row.text(2)?)?,dialect:store::os_io::ArtifactDialect{artifact_kind:owned.text(row.text(3)?)?,standard:owned.text(row.text(4)?)?,subset:owned.text(row.text(5)?)?}}))}else{None};owned.checkpoint()?;Ok(Self{exaggeration,imported_features_json,mesh})}
 fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;if dialect.artifact_kind!="s.gis.gisterrain"||dialect.standard!="1"||dialect.subset!="*"{return Err(String::from("GIS terrain does not own this semantic subset").into())}let restored=Self::from_sqlite_database(database,control)?;if self.exaggeration.to_bits()!=restored.exaggeration.to_bits()||self.imported_features_json!=restored.imported_features_json||self.mesh!=restored.mesh{return Err(String::from("GIS terrain owned identity differs").into())}Ok(store::io_schema::IoOutcome::clean(()))}
}
